import{_ as o,o as r,c as a,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const s="/MoMAWork-/assets/wechat-qr._jEgA8FU.jpg",c=JSON.parse('{"title":"OPC 实战营","description":"","frontmatter":{},"headers":[],"relativePath":"community/index.md","filePath":"community/index.md"}'),e={name:"community/index.md"};function l(i,t,d,g,h,p){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="opc-实战营" tabindex="-1">OPC 实战营 <a class="header-anchor" href="#opc-实战营" aria-label="Permalink to &quot;OPC 实战营&quot;">​</a></h1><h2 id="一人公司的-ai-作业本" tabindex="-1">一人公司的 AI 作业本 <a class="header-anchor" href="#一人公司的-ai-作业本" aria-label="Permalink to &quot;一人公司的 AI 作业本&quot;">​</a></h2><blockquote><p>一个人，一支 AI 团队，一门跑得起来的生意。 <strong>不聊概念，只交作业。</strong></p></blockquote><div style="text-align:center;margin:24px 0 8px;"><img src="'+s+'" alt="扫码加我微信，我拉你进群" width="200" height="200" style="border-radius:12px;box-shadow:0 4px 16px rgba(0,0,0,0.12);"><div style="font-size:14px;line-height:1.9;color:var(--vp-c-text-2);margin-top:12px;"><strong>扫码加我微信，我拉你进群</strong><br> 微信 / 邮件：<code>1972597219@qq.com</code></div></div><hr><h2 id="先说一件很多人不愿意承认的事" tabindex="-1">先说一件很多人不愿意承认的事 <a class="header-anchor" href="#先说一件很多人不愿意承认的事" aria-label="Permalink to &quot;先说一件很多人不愿意承认的事&quot;">​</a></h2><p><strong>一个人做事，最难的从来不是能力，是&quot;没人跟你一起&quot;。</strong></p><ul><li>想到一个好点子，没人接你的话；</li><li>卡在一个环节上，没人拉你一把；</li><li>好不容易做完一件漂亮的事，<strong>没人知道你做了</strong>；</li><li>做砸了，更没人告诉你错在哪。</li></ul><p>你可以用 AI 补上&quot;人手&quot;——这是 MomaWork 存在的意义。 但 AI <strong>补不上&quot;同行&quot;</strong>。</p><p>OPC 社区就是来补这一块的。</p><hr><h2 id="opc-是什么" tabindex="-1">OPC 是什么 <a class="header-anchor" href="#opc-是什么" aria-label="Permalink to &quot;OPC 是什么&quot;">​</a></h2><p>OPC = <strong>One Person Company</strong>，一人公司。</p><p>但在我们这里，它<strong>不是</strong>一个工商注册形态，而是一种工作方式：</p><blockquote><p>一个人，把原本需要一支团队做的事，<strong>拆</strong>成一件件能交给 AI 干的事。</p></blockquote><p>会拆的人，一个人顶一支团队。 不会拆的人，AI 再多，也只是个更聪明的搜索框。</p><p><strong>我们聚在一起，就是为了把&quot;拆&quot;这件事练熟。</strong></p><hr><h2 id="我们和别的社区不一样在哪里" tabindex="-1">我们和别的社区不一样在哪里 <a class="header-anchor" href="#我们和别的社区不一样在哪里" aria-label="Permalink to &quot;我们和别的社区不一样在哪里&quot;">​</a></h2><p>讲一人公司的地方很多。绝大部分在讲<strong>为什么</strong>——趋势、自由、机会、睡后收入。</p><p>我们不讲这个。不是因为它错，而是因为<strong>讲完改变不了任何事</strong>。</p><p>我们只讲<strong>怎么做</strong>，而且必须落到看得见的东西上：</p><table tabindex="0"><thead><tr><th></th><th>别人</th><th>我们</th></tr></thead><tbody><tr><td>内容</td><td>观点与故事</td><td><strong>作业</strong>：可复现的操作步骤</td></tr><tr><td>证明</td><td>收入截图</td><td><strong>交付物</strong>：文件、表格、Skill、上线的东西</td></tr><tr><td>归宿</td><td>收藏夹</td><td><strong>资产</strong>：Skill 集市、团队模板、案例库</td></tr></tbody></table><p>所以我们的规矩只有一条，很简单：</p><blockquote><p><strong>别人在讲&quot;我做到了&quot;，我们只讲&quot;你也来交一份&quot;。</strong></p></blockquote><hr><h2 id="在这里-你会得到四样东西" tabindex="-1">在这里，你会得到四样东西 <a class="header-anchor" href="#在这里-你会得到四样东西" aria-label="Permalink to &quot;在这里，你会得到四样东西&quot;">​</a></h2><h3 id="_1️⃣-一套成体系的方法-不是零散技巧" tabindex="-1">1️⃣ 一套成体系的方法，不是零散技巧 <a class="header-anchor" href="#_1️⃣-一套成体系的方法-不是零散技巧" aria-label="Permalink to &quot;1️⃣ 一套成体系的方法，不是零散技巧&quot;">​</a></h3><p>MomaWork 白皮书 <strong>28 章</strong>，从「怎么把需求讲清楚」一路讲到「多 Agent 系统设计」。 你不用自己摸索，也不用在几百个短视频里捞碎片。</p><p>👉 <a href="/MoMAWork-/bluebook/">白皮书总览</a> · <a href="/MoMAWork-/easy/">易懂版（0 基础）</a></p><h3 id="_2️⃣-一批能直接用的装备" tabindex="-1">2️⃣ 一批能直接用的装备 <a class="header-anchor" href="#_2️⃣-一批能直接用的装备" aria-label="Permalink to &quot;2️⃣ 一批能直接用的装备&quot;">​</a></h3><p><strong>33 个内置技能</strong>、<strong>11 位内置专家</strong>、团队模板（包括现成的「一人公司·做内容」）。 遇到什么事，喊哪件装备——我列给你，不用背。</p><h3 id="_3️⃣-一个会给你反馈的同行圈子" tabindex="-1">3️⃣ 一个会给你反馈的同行圈子 <a class="header-anchor" href="#_3️⃣-一个会给你反馈的同行圈子" aria-label="Permalink to &quot;3️⃣ 一个会给你反馈的同行圈子&quot;">​</a></h3><p>你交的作业，有人看、有人评、有人拿去改一改自己用。 <strong>被复用，是对一份作业最高的评价。</strong></p><h3 id="_4️⃣-一份你自己的沉淀" tabindex="-1">4️⃣ 一份你自己的沉淀 <a class="header-anchor" href="#_4️⃣-一份你自己的沉淀" aria-label="Permalink to &quot;4️⃣ 一份你自己的沉淀&quot;">​</a></h3><p>每交一次作业，就多一个 Skill、多一个模板、多一个能复用的零件。 一年下来，你手上不是&quot;学了很多&quot;，而是<strong>攒下了一套只属于你的生产系统</strong>。</p><hr><h2 id="我们不做什么-看清楚再决定要不要来" tabindex="-1">我们不做什么（看清楚再决定要不要来） <a class="header-anchor" href="#我们不做什么-看清楚再决定要不要来" aria-label="Permalink to &quot;我们不做什么（看清楚再决定要不要来）&quot;">​</a></h2><p>这一节和上面一样重要，因为我们宁可门口冷清，也不想里面变味：</p><ul><li>❌ <strong>不做 AI 工具资讯搬运</strong>——网上到处都是，我们不做第二份。</li><li>❌ <strong>不做&quot;月入 X 万&quot;的财富故事</strong>——一旦开始晒收入，来的人就不是来干活的。</li><li>❌ <strong>不做免费资源大礼包</strong>——靠白嫖聚起来的人不交作业，只会稀释气氛。</li><li>❌ <strong>不追求人数</strong>——前 100 个人决定这个社区的气质。</li><li>❌ <strong>不做没有交付物的活动</strong>——任何活动，必须产出一份能存档的东西。</li></ul><p><strong>如果你要的是&quot;看看别人怎么发财&quot;，这里不适合你，我不耽误你时间。</strong><strong>如果你手上正好有一件想干成的事，留下。</strong></p><hr><h2 id="社区怎么运转-六个栏目" tabindex="-1">社区怎么运转（六个栏目） <a class="header-anchor" href="#社区怎么运转-六个栏目" aria-label="Permalink to &quot;社区怎么运转（六个栏目）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>栏目</th><th>干什么</th></tr></thead><tbody><tr><td>🚩 <strong>新人报到</strong></td><td>进来先说说你是谁、在做什么、卡在哪</td></tr><tr><td>📓 <strong>作业本</strong></td><td><strong>社区的心脏</strong>：把你的实战过程交上来</td></tr><tr><td>🔧 <strong>Skill 集市</strong></td><td>把作业沉淀成可复用的 Skill，互相取用</td></tr><tr><td>👥 <strong>组队共创</strong></td><td>一个人啃不动的活，喊人一起</td></tr><tr><td>📅 <strong>活动日历</strong></td><td>每周任务、双周分享、月度上墙</td></tr><tr><td>🧰 <strong>资源库</strong></td><td>模板、提示词、清单，都是成员交上来的</td></tr></tbody></table><blockquote><p><strong>注意：&quot;作业本&quot;排在第一位，不是装饰。</strong> 一个社区的气质，取决于它默认鼓励什么。我们默认鼓励&quot;交出来&quot;。</p></blockquote><hr><h2 id="三条规矩" tabindex="-1">三条规矩 <a class="header-anchor" href="#三条规矩" aria-label="Permalink to &quot;三条规矩&quot;">​</a></h2><ol><li><strong>不晒收入，只晒交付物</strong>——证明你做成过一件事的方式，是把那份东西拿出来。</li><li><strong>不发外部资源包、不发硬广告</strong>——作业里可以带生意，广告里不许带作业。</li><li><strong>提问带上背景 + 已试过什么 + 卡在哪</strong>——这样别人才答得上。</li></ol><p><strong>一条铁律：交作业 24 小时内必须有回应。</strong> 回应慢一次，就少一个人交第二次。</p><hr><h2 id="怎么加入" tabindex="-1">怎么加入 <a class="header-anchor" href="#怎么加入" aria-label="Permalink to &quot;怎么加入&quot;">​</a></h2><p><strong>第一步</strong>：扫上面的码加我微信，我拉你进群（也可以先发邮件到 <code>1972597219@qq.com</code>）。</p><p><strong>第二步</strong>：进群后做三件事——</p><ol><li>改备注：<code>昵称 · 在做什么</code></li><li>到 🚩 新人报到 发一条：<strong>我是谁 / 我在做什么 / 我现在卡在哪</strong></li><li>领走本周的一个任务（不用全做，挑一个）</li></ol><p><strong>第三步</strong>：做完交作业。哪怕只是一张截图、一段文字。 <strong>先交一份不完美的，好过想一个月交一份完美的。</strong></p><hr><h2 id="📓-本周任务-第-1-周" tabindex="-1">📓 本周任务（第 1 周） <a class="header-anchor" href="#📓-本周任务-第-1-周" aria-label="Permalink to &quot;📓 本周任务（第 1 周）&quot;">​</a></h2><blockquote><p><strong>把一件你每周都要重复做的事，交给 AI 做一遍</strong></p></blockquote><p><strong>为什么做这个</strong>：先别管学到多少，先尝到一次&quot;真的省事了&quot;。</p><p><strong>怎么做（≤40 分钟）</strong></p><ol><li>想一件你<strong>每周至少做一次</strong>、每次要花 <strong>10 分钟以上</strong>的事（写周报、整理表格、回邮件、做汇总、写通知……）</li><li>打开 MomaWork，用大白话把这件事讲给它——<strong>不用懂提示词</strong>，怎么跟同事说就怎么说</li><li>让它先做一遍，你只改不对的地方</li><li>记下两个数：<strong>以前要多久 / 现在要多久</strong></li></ol><p><strong>交付物</strong>：一张前后对比（截图最好，一句话也行） <strong>交到哪</strong>：加我微信直接发我，或在群里 @我 <strong>截止</strong>：本周日</p><p><strong>本周上墙</strong>：等你——第一份作业交上来，就上墙 <strong>本周交作业数</strong>：0（你交了就是 1）</p><hr><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>我们不做一个大而热闹的地方。 我们做一个<strong>小而能生产</strong>的地方。</p><blockquote><p>一个人，一支 AI 团队，一门跑得起来的生意。 <strong>不聊概念，只交作业。</strong></p></blockquote><hr><p><strong>合作 / 赞助 / 想一起做这事</strong>：<code>1972597219@qq.com</code>（或扫码加我微信）</p>',69)])])}const q=o(e,[["render",l]]);export{c as __pageData,q as default};
